"""Summarize before/current whole-fight policy replay without inventing damage."""
import hashlib,json,sys
from pathlib import Path
p=Path(sys.argv[1]);before={x['label']:x for x in json.loads((p/'before/summary.json').read_text())};current={x['label']:x for x in json.loads((p/'current/summary.json').read_text())}
assert len(before)==len(current)==5
lines=['# VPR whole-fight log-backed production-selection replay','','Each cell is baseline -> current; reference is the observed player. All counts are modeled or observed casts, not a DPS estimate.','','| Fight | Reawaken/Ouroboros | Reference RA/Ouro | Fury | Ire | Vice | Gauge overcap | Ouro under observed potion |','|---|---|---|---|---|---|---|---|']
for name in ['light','cruiser','heavy','dmu','fru']:
 b=before[name];a=current[name]
 for x in [b,a]:
  assert x['Illegal']==0 and x['GcdIdleSeconds']<=2 and not x['unfinished']
  assert x['counts']['Reawaken']==x['counts']['Ouroboros']
 def pair(key):return str(b['counts'].get(key,0))+' -> '+str(a['counts'].get(key,0))
 lines.append(f"| {name} | {pair('Reawaken')} / {pair('Ouroboros')} | {a['reference']['Reawaken']}/{a['reference']['Ouroboros']} | {pair('Uncoiled Fury')} | {pair('Serpent\'s Ire')} | {pair('Vicewinder')} | {b['overcapGauge']} -> {a['overcapGauge']} | {b['packageStats']['ouroborosUnderPotion']} -> {a['packageStats']['ouroborosUnderPotion']} |")
lines += ['',f"Completed sequences: {sum(x['counts']['Ouroboros'] for x in before.values())} -> {sum(x['counts']['Ouroboros'] for x in current.values())}; reference {sum(x['reference']['Ouroboros'] for x in current.values())}. Gauge overcap: {sum(x['overcapGauge'] for x in before.values())} -> {sum(x['overcapGauge'] for x in current.values())}. No coil overcap in either model run.",'','The same boundary and external fixtures run both production source snapshots. Reference future casts never choose the next model action or update the model gauge. Reference is used only for counts and initial/external environmental calibration. All five full durations run, including target losses and phase transitions. Assertions reject illegal resource transitions, unfinished/restarted Reawaken sequences, and more than 2 seconds of unexplained active-target GCD idle. Maximum idle across runs is '+str(max(x['GcdIdleSeconds'] for x in list(before.values())+list(current.values())))+' seconds.','','## Evidence and limits','','- The complete 190,377 cached events were reduced after checking exhausted pagination (12 pages). The fixture records source event and page counts. External party buffs and debuffs preserve exact observed apply/remove windows. Potions are observed human Medicated windows; autonomous potion usage is deliberately disabled. These runs do not validate auto-potion ordering.','- Both VPR production GeneralGCD, EmergencyAbility, AttackAbility, action hooks, tracker, scheduler and policy bodies are compiled from source with SDK Roslyn. The native action boundary and game state are modeled, not the Dalamud native action engine. Readiness enforces Ire 120s, two Vice charges recharging sequentially every 40s, coil cap 3, offering cap 100, 50-paid/free-token entry, Dread/Generation exclusivity, own combo state and two follow-up weave slots.','- Normal finishers grant 10 offering; Hunter/Swift Coils grant 5 each; Vice and Ire grant one coil and no offering. Resource conservation in the observed references supports these assumptions. All model resources are advanced by its own selected actions. Pull starts at zero gauge/coils with two Vice charges and Ire ready.','- Target switching, targetability, and target last outgoing damage are known log-derived environmental fixtures. Target last activity is used as a perfect target lifetime approximation; future target losses emulate available encounter timeline data. This does not validate live TTK inference, untargetable detection, target choice, or arbitrary player movement.','- Per-action GCD spacing uses the median observed next-GCD interval below 4.5s (thus includes human/network timing). The normal combo is reduced to a three-step resource/deadline-equivalent chain with representative finisher variants; honed/venom/position damage and exact native adjusted-action IDs are not validated. Facing is always favorable; melee range is always available while the target is available. No movement, autos, damage, party contribution, crit, potency weighting or rDPS model exists. Historical patch logs are compared under current level-100 resource rules.','- Combo deadline is 30s, finisher venom 60s, Dread/Reawaken/token and Coil venom deadlines 30s. A 30s modeled pending-followup expiry is a boundary assumption; exact native SerpentCombo lifetime is not established here. Pending expiries are counted in the summaries.','- DMU loses one free token in both baseline and current (Ire about 855s / 860s before a target loss; next Reawaken occurs after the 30s token). The unchanged independent Ire policy also leaves a final token unspent in both. This remains visible and is not a new regression.','- The broad initial planner was rejected: FRU party-buffed Reawaken/Generation/Legacy/Ouroboros fell from 14/49/48/12 to 10/39/38/10, while Fury/Twins rose from 15/25 to 23/39. Allocation-only and early/final-package branches independently reproduced adverse alignment indicators. Those experiment outputs remain under rejected-broad, no-allocation, no-package, no-both, potion-only, final-only and early-only.', '- Final accepted source keeps only the paid-potion release when the learned next party window does not overlap the remaining potion. Runtime triple forecasting, nominal predicted-window prefire, final-target package prefire and token resource allocation were removed after the replay regressions. These broader gaps are deferred rather than claimed fixed.', '- Final FRU buffed action counts exactly match baseline. Light potion Ouroboros increases 2 -> 5 with unchanged total Reawaken/Fury and zero gauge overcap. Cruiser gains one complete sequence and one Fury; gauge overcap falls 40 -> 10 and potion Ouroboros rises 3 -> 5. DMU/heavy/FRU whole-sequence totals stay unchanged.', '- The final timing tradeoff is visible: light party-buffed Generation/Legacy counts fall 42/42 -> 40/40 while Reawaken/Ouroboros stay 10/10; cruiser party-buffed Reawaken/Generation/Legacy/Ouroboros fall 12/48/47/10 -> 11/44/43/9 while total completed sequences rise 19 -> 20. Cruiser Dread expiry rises 0 -> 1 at a target loss. Without a calibrated damage model these cannot establish exact net DPS, and no performance gain is quantified. Current totals still differ from observed players; top-player parity is not claimed.','','Source SHA256:']
for label,folder in [('baseline',p/'before-source'),('current',Path(sys.argv[2])/'RotationSolver/RebornRotations/Melee')]:
 for file in ['VPR_Reborn.cs','VPR_SyncPlus.cs']:lines.append('- '+label+' '+file+': `'+hashlib.sha256((folder/file).read_bytes()).hexdigest().upper()+'`')
proxy={'Reawaken':750,'Ouroboros':1150,'Uncoiled Fury':680,'Uncoiled Twinfang':170,'Uncoiled Twinblood':170}
proxy.update({n+' Generation':680 for n in ['First','Second','Third','Fourth']})
proxy.update({n+' Legacy':320 for n in ['First','Second','Third','Fourth']})
lines+=['','## Normalized selected-family coverage proxy','','These current-guide potency constants normalize only Reawaken/Generations/Legacies/Ouroboros and Fury/Twins: Reawaken 750, Generation 680, Legacy 320, Ouroboros 1150, Fury 680, Twins 170 each. Counts are summed before any damage multiplier. This is a limited coverage proxy, not full-rotation potency, damage, rDPS, or a simulation of potion strength. Normal combos, Vice/Coils/Twins, autos, stats, crit, tincture dexterity caps and party buff strength are omitted. Constants were checked against the current official Viper job guide during independent review.','','| Fight | Selected-family total | Covered by any party buff | Covered by observed potion |','|---|---|---|---|']
for name in ['light','cruiser','heavy','dmu','fru']:
 values=[]
 for variant in ['before','current']:
  rows=json.loads((p/variant/(name+'-timeline.json')).read_text())
  values.append([sum(proxy.get(r['name'],0) for r in rows if gate(r)) for gate in [lambda r:True,lambda r:r['buffs']>0,lambda r:r['medicated']]])
 lines.append('| '+name+' | '+' | '.join(str(values[0][i])+' -> '+str(values[1][i]) for i in range(3))+' |')
(p/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('\n'.join(lines[:13]))
